public class Main {
  public static void main(String[] args) {
    int[] a = {1, 2, 3};
    try {
      System.out.print("A");
      System.out.print(a[3]);
      System.out.print("B");
    } catch (ArrayIndexOutOfBoundsException e) {
      System.out.print("C");
    } finally {
      System.out.print("D");
    }
    System.out.print("E");
  }
}
